<?php
$p=$product;
function productInput(string $label,string $name,array $p,string $type='text',bool $required=false,string $extra=''):void { ?><label><?= e($label) ?><input name="<?= e($name) ?>" type="<?= e($type) ?>" value="<?= e((string)($p[$name]??'')) ?>" <?= $required?'required':'' ?> <?= $extra ?>></label><?php }
function productOptions(array $rows,mixed $selected,bool $category=false):void {foreach($rows as $row){if((!empty($row['archived_at']) || ($row['status']??'active')!=='active') && (string)$row['id']!==(string)$selected)continue;?><option value="<?= (int)$row['id'] ?>" <?= (string)$selected===(string)$row['id']?'selected':'' ?> <?= isset($row['category_id'])?'data-parent="'.(int)$row['category_id'].'"':'' ?>><?= e($row['name']) ?><?= ($row['status']??'active')!=='active'?' (inactive)':'' ?></option><?php }}
function specificationRow(array $row,int|string $index):void { ?><div class="repeat-row specification-row"><input aria-label="Specification name" name="specifications[<?= e((string)$index) ?>][label]" placeholder="Size / material / voltage" maxlength="80" value="<?= e($row['label']??'') ?>"><input aria-label="Specification value" name="specifications[<?= e((string)$index) ?>][value]" placeholder="Value" maxlength="250" value="<?= e($row['value']??'') ?>"><button type="button" class="icon-button" data-remove-row title="Remove specification" aria-label="Remove specification">×</button></div><?php }
function fitmentRow(array $f,int|string $index,array $masters,bool $showYears=true):void { $prefix='fitments['.$index.']'; ?><div class="fitment-row" data-fitment-row><div class="product-fields"><label>Manufacturer<select name="<?= e($prefix) ?>[manufacturer_id]" data-bike-maker required><option value="">Select manufacturer</option><?php productOptions($masters['vehicle_manufacturers'],$f['manufacturer_id']??''); ?></select></label><label>Model<select name="<?= e($prefix) ?>[model_id]" data-bike-model required><option value="">Select model</option><?php productOptions($masters['vehicle_models'],$f['model_id']??''); ?></select></label><label>Variant (optional)<select name="<?= e($prefix) ?>[variant_id]" data-bike-variant><option value="">Not specified</option><?php productOptions($masters['vehicle_variants'],$f['variant_id']??''); ?></select></label><?php if($showYears): ?><label>From year<input type="number" name="<?= e($prefix) ?>[year_from]" min="1900" max="<?= (int)date('Y')+2 ?>" value="<?= e((string)($f['year_from']??'')) ?>"></label><label>To year<input type="number" name="<?= e($prefix) ?>[year_to]" min="1900" max="<?= (int)date('Y')+2 ?>" value="<?= e((string)($f['year_to']??'')) ?>"></label><?php else: foreach(['year_from','year_to'] as $year): if(!empty($f[$year])): ?><input type="hidden" name="<?= e($prefix) ?>[<?= e($year) ?>]" value="<?= e((string)$f[$year]) ?>"><?php endif; endforeach; endif; ?><label>Fitment notes<input name="<?= e($prefix) ?>[notes]" maxlength="500" placeholder="Front / rear, disc / drum…" value="<?= e($f['notes']??'') ?>"></label></div><div class="fitment-footer"><?php if(can(current_user(),'products.verify_fitment')): ?><label class="check-label"><input type="checkbox" name="<?= e($prefix) ?>[verified]" value="1" <?= !empty($f['verified_at']) || ($f['verified']??'')==='1'?'checked':'' ?>> Fitment verified</label><?php else: ?><span class="subtle-text"><?= !empty($f['verified_at'])?'Previously verified':'Unverified fitment' ?></span><?php endif; ?><button class="button button-small" type="button" data-remove-row>Remove bike</button></div></div><?php }
?>
<section class="page-heading"><div><h1><?= $id?'Edit product':($duplicated?'Duplicate product':'Add product') ?></h1><p><?= $id?'Update product information. Stock changes belong in inventory operations.':'One physical part, one SKU. Bike mappings share this product’s inventory.' ?></p></div><a class="button" href="<?= e(url('/products')) ?>">Back to products</a></section>
<?php if($error): ?><div class="alert" role="alert"><?= e($error) ?></div><?php endif; ?><?php if($duplicated): ?><div class="info-strip">Copied product information only. A new SKU will be generated; opening stock and verification have not been copied.</div><?php endif; ?>
<form method="post" action="<?= e(url('/products/save')) ?>" id="product-form" data-can-verify-fitment="<?= can(current_user(),'products.verify_fitment')?'1':'0' ?>"><input type="hidden" name="csrf" value="<?= e(csrf()) ?>"><input type="hidden" name="creation_key" value="<?= e($key) ?>"><?php if($id): ?><input type="hidden" name="id" value="<?= $id ?>"><input type="hidden" name="lock_version" value="<?= e((string)($p['lock_version']??'')) ?>"><?php endif; ?>
<div class="product-form-grid"><section class="surface product-section"><h2>Basic information</h2><div class="product-fields"><?php productInput('Product name *','name',$p,'text',true,'maxlength="190"'); ?><label>Category *<select name="category_id" data-product-category required><option value="">Choose category</option><?php productOptions($masters['categories'],$p['category_id']??''); ?></select></label><div class="subcategory-field"><label for="subcategory-search">Subcategory</label><input id="subcategory-search" type="search" autocomplete="off" placeholder="Search subcategories…" role="combobox" aria-autocomplete="list" aria-expanded="false" aria-controls="subcategory-options" data-subcategory-search><input type="hidden" name="subcategory_id" value="<?= e((string)($p['subcategory_id']??'')) ?>" data-product-subcategory><div id="subcategory-options" class="subcategory-options" role="listbox" hidden></div><span class="subtle-text" data-subcategory-selected aria-live="polite"><?= e($p['subcategory_name']??'No subcategory') ?></span></div><label>Brand<select name="brand_id"><option value="">No brand</option><?php productOptions($masters['brands'],$p['brand_id']??''); ?></select></label><label>Status<select name="status"><option value="active">Active</option><option value="inactive" <?= ($p['status']??'')==='inactive'?'selected':'' ?>>Inactive</option></select></label><?php if($id): ?><label class="wide">Description<textarea name="description" rows="2" maxlength="5000"><?= e($p['description']??'') ?></textarea></label><?php elseif($duplicated): ?><input type="hidden" name="description" value="<?= e($p['description']??'') ?>"><?php endif; ?></div></section>
<section class="surface product-section"><h2>Product identification</h2><p class="subtle-text">SKU: <strong><?= $id?e($p['sku']??''):'Generated uniquely when saved' ?></strong></p><div class="product-fields"><?php productInput('Manufacturer part number / OEM code','part_number',$p,'text',false,'maxlength="120"'); ?><label class="wide">Search aliases / local names<input name="aliases" maxlength="3000" value="<?= e($p['aliases']??'') ?>" placeholder="Separate names with commas"></label></div><h2>Specifications <span class="subtle-text">optional</span></h2><div id="specification-rows"><?php foreach(($p['specifications']??[]) as $i=>$row)specificationRow($row,$i); ?></div><button class="button button-small" type="button" data-add-specification>＋ Add specification</button></section>
<section class="surface product-section wide"><h2>Compatible bikes <span class="subtle-text">optional · newly added mappings are unverified</span></h2><div class="fitment-picker-toolbar"><button class="button button-small" type="button" data-open-bike-picker>Select Compatible Bikes</button><span class="subtle-text" id="fitment-count" aria-live="polite"></span></div><div id="fitment-rows"><?php foreach(($p['fitments']??[]) as $i=>$f)fitmentRow($f,$i,$masters,(bool)$id); ?></div><?php if(current_user()['role']==='shop_owner'): ?> <a class="text-link" href="<?= e(url('/product-masters')) ?>&amp;type=vehicle_manufacturers" target="_blank" rel="noopener">Manage bike catalogue ↗</a><?php endif; ?></section>
<section class="surface product-section"><h2>Pricing &amp; tax</h2><div class="product-fields pricing-fields"><label>MRP (optional)<input name="mrp" type="number" min="0" step="0.01" value="<?= e((string)($p['mrp']??'')) ?>" data-price-mrp></label><label>Purchase discount (%)<input name="purchase_discount" type="number" min="0" max="100" step="0.01" value="<?= e((string)($p['purchase_discount']??'')) ?>" data-price-discount="purchase"></label><label>Cost price (₹) *<input name="purchase_price" type="number" min="0" step="0.01" required value="<?= e((string)($p['purchase_price']??'')) ?>" data-price-value="purchase"><small class="price-calculated-hint" data-price-hint="purchase" hidden>Calculated from MRP and purchase discount</small></label><label>Selling discount (%)<input name="selling_discount" type="number" min="0" max="100" step="0.01" value="<?= e((string)($p['selling_discount']??'')) ?>" data-price-discount="selling"></label><label>Selling price (₹) *<input name="selling_price" type="number" min="0" step="0.01" required value="<?= e((string)($p['selling_price']??'')) ?>" data-price-value="selling"><small class="price-calculated-hint" data-price-hint="selling" hidden>Calculated from MRP and selling discount</small></label><div class="price-profit-summary"><strong>Profit per unit <span data-price-profit>—</span></strong><strong>Gross margin <span data-price-margin>—</span></strong></div><label>HSN code<input name="hsn_code" type="text" maxlength="20" value="<?= e((string)($p['hsn_code']??'')) ?>"></label><label>Tax rate<select name="tax_rate_id"><option value="">Not configured</option><?php productOptions($masters['tax_rates'],$p['tax_rate_id']??''); ?></select></label></div></section>
<section class="surface product-section"><h2><?= $id?'Inventory settings':'Initial inventory' ?></h2><div class="product-fields"><?php if(!$id): ?><?php productInput('Opening stock quantity','opening_quantity',$p+['opening_quantity'=>'0'],'number',true,'min="0" step="0.000001"');productInput('Opening purchase cost per item (required if stock > 0)','opening_cost',$p,'number',false,'min="0" step="0.000001"');productInput('Opening stock date','opening_date',$p+['opening_date'=>(new DateTimeImmutable('today',new DateTimeZone('Asia/Kolkata')))->format('Y-m-d')],'date',true); ?><?php else: ?><p class="subtle-text wide">Existing stock and movement history are preserved. Use inventory operations for subsequent changes.</p><?php endif; ?><?php productInput('Minimum stock level','reorder_level',$p+['reorder_level'=>'0'],'number',true,'min="0" step="0.000001"');productInput('Rack location','rack_location',$p,'text',false,'maxlength="80"'); ?></div></section></div>
<footer class="product-form-footer"><a class="button" href="<?= e(url('/products')) ?>">Cancel</a><button class="button button-primary" type="submit"><?= $id?'Save changes':'Create product' ?></button><span role="status"></span></footer></form>
<dialog class="bike-picker-dialog" id="bike-picker-dialog" aria-labelledby="bike-picker-title"><div class="bike-picker-heading"><div><h2 id="bike-picker-title">Select Compatible Bikes</h2><p class="subtle-text">Choose bike models. You can add variants and fitment details afterward.</p></div><button type="button" class="icon-button" data-close-bike-picker aria-label="Close bike picker">×</button></div><div class="bike-picker-filters"><label>Manufacturer<select id="bike-picker-manufacturer"><option value="">All manufacturers</option><?php foreach($masters['vehicle_manufacturers'] as $maker): ?><option value="<?= (int)$maker['id'] ?>"><?= e($maker['name']) ?></option><?php endforeach; ?></select></label><label>Search manufacturer or model<input id="bike-picker-search" type="search" autocomplete="off" placeholder="Search bikes…"></label></div><div class="bike-picker-actions"><button type="button" class="button button-small" id="bike-picker-select-all">Select all filtered</button><button type="button" class="button button-small" id="bike-picker-clear">Clear selection</button><strong id="bike-picker-count" aria-live="polite">0 bikes selected</strong></div><div class="bike-picker-list" id="bike-picker-list"></div><footer><button type="button" class="button" data-cancel-bike-picker>Cancel</button><button type="button" class="button button-primary" id="bike-picker-confirm">Confirm Selection</button></footer></dialog>
<template id="specification-template"><?php specificationRow([],'__INDEX__'); ?></template><template id="fitment-template"><?php fitmentRow([],'__INDEX__',$masters,(bool)$id); ?></template><script type="application/json" id="product-master-data"><?= json_encode($masters,JSON_HEX_TAG|JSON_HEX_AMP|JSON_HEX_APOS|JSON_HEX_QUOT) ?></script>
